arguments.command:
cd /app/data; python3 - <<'E'
import glob,gzip,csv,io,collections
for f in sorted(glob.glob('*')):
    b=open(f,'rb').read()
    if b[:2]==b'\x1f\x8b': b=gzip.decompress(b); print(f,'GZ')
    if b[:2] in (b'\xff\xfe',b'\xfe\xff'): print(f,'UTF16')
    if b[:3]==b'\xef\xbb\xbf': print(f,'BOM8')
    t=b[:300]
    if b'charset' in t: print(f,'charset',t[:150])
E
grep -h -a 'BN overflow' -B2 -A2 east* | head -20

