    "FW2": {"len": 43, "type": (0, 1), "id": (1, 10), "shipped": (10, 18), "weight": (18, 26), "status": (26, 27),
            "date": "ymd", "unit": "kg", "scale": Decimal("0.01")},
    "FW3": {"len": 41, "id": (0, 9), "shipped": (9, 16), "type": (16, 17), "weight": (17, 24), "status": (24, 25),
            "date": "doy", "unit": "lb", "scale": Decimal("0.1")},
}


def parse_fixed(text):
    seq = None
    layout = None
    out = []
    by_len = {v["len"]: k for k, v in LAYOUTS.items()}
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if "\f" in line or re.match(r"^\s*SOUTH DEPOT", line) or not line.strip():
            continue
        if line.startswith("#"):
            m = re.match(r"^#LAYOUT\s+(\S+)", line)
            if m:
                layout = m.group(1)
            m = re.match(r"^#SEQ\s+(\d+)", line)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        name = by_len.get(len(line))
        if name is None:
            if layout in LAYOUTS and len(line) < LAYOUTS[layout]["len"]:
                name = layout
                line = line.ljust(LAYOUTS[layout]["len"])
            else:
                warn("south: unmatched line length %d" % len(line))
                continue
        L = LAYOUTS[name]
        g = lambda k: line[L[k][0]:L[k][1]]  # noqa: E731
        try:
            typ = g("type")
            if norm_type(typ) == "void":
                out.append(make_record(g("id"), typ, None, None, None))
                continue
            s = g("shipped")
            if L["date"] == "doy":
                date = doy_date(int(s[:4]), int(s[4:]))
            else:
                date = dt.date(int(s[:4]), int(s[4:6]), int(s[6:]))
            kg = int(g("weight")) * L["scale"] * KG[L["unit"]]
            st = FW_STATUS.get(g("status").strip().upper(), "")
            out.append(make_record(g("id"), typ, date, kg, st))
        except Exception as e:  # noqa: BLE001
            warn("south: skipped %r: %s" % (line[:60], e))
    return seq, out


def parse_file(depot, path):
    b = read_raw(path)
    if depot == "central":
        return parse_xml(b)
    text = decode(b)
    if depot == "north":
        return parse_jsonl(text)
    if depot == "south":
        return parse_fixed(text)
    if depot in DELIM:
        seq, recs = parse_delimited(depot, text)
        if depot == "harbor":
            pass
        return seq, recs
    warn("unknown depot %s" % depot)
    return None, []


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0].lower()
        exports.setdefault(depot, [])
        try:
            seq, recs = parse_file(depot, path)
        except Exception as e:  # noqa: BLE001
            warn("%s: failed: %s" % (name, e))
            continue
        exports[depot].append((seq if seq is not None else -1, name, recs))

    corrections = resends = 0
    current = {}
    for depot, files in exports.items():
        files.sort(key=lambda x: (x[0], x[1]))
        cur = {}
        for _, _, recs in files:
            for r in recs:
                if r is None:
                    continue
                n = r["num"]
                if r["type"] == "new":
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["type"] == "correction":
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur

    rank = {d: i for i, d in enumerate(PRIORITY)}
    order = sorted(current, key=lambda d: (rank.get(d, len(rank)), d))
    kept = {}
    handovers = 0
    seen = {}
    for depot in order:
        for n, r in current[depot].items():
            seen[n] = seen.get(n, 0) + 1
            if n not in kept:
                kept[n] = (depot, r)
    handovers = sum(1 for c in seen.values() if c > 1)

    depots = {d: [0, Decimal(0)] for d in exports}
    months = {}
    for n, (depot, r) in kept.items():
        if not r["counted"]:
            continue
        depots[depot][0] += 1
        depots[depot][1] += r["kg"]
        m = months.setdefault(r["month"], [0, Decimal(0)])
        m[0] += 1
        m[1] += r["kg"]

    def fmt(v):
        return float(v[1].quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

    result = {
        "depots": {d: {"shipments": v[0], "total_kg": fmt(v)} for d, v in sorted(depots.items())},
        "months": {k: {"shipments": v[0], "total_kg": fmt(v)} for k, v in sorted(months.items())},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main()
